+/**
+ * 正規化批次輸入的邀請碼：trim、去空、去重
+ */
+function normalizeBatchCodes(codes: string[]): string[] {
+  const normalized = codes
+    .flatMap((c) => c.split(/[\n,]/))
+    .map((c) => c.trim())
+    .filter(Boolean);
+  return [...new Set(normalized)];
+}
+
+/**
+ * 批次創建邀請碼（同一組設定、多個 code）
+ * 需要 write-invitationCodes 權限
+ * 部分成功時回報 created、duplicateCodes，不拋錯
+ */
+export async function createInvitationCodesBatch(
+  data: CreateInvitationCodesBatchData
+): Promise<CreateInvitationCodesBatchResult> {
+  const user = await currentUser();
+  if (!user?.id) {
+    return { success: false, created: 0, failed: 0, duplicateCodes: [], error: 'Unauthorized' };
+  }
+
+  const hasPermission = await checkCurrentUserPermission(
+    'write-invitationCodes' as AdminPermissionCode
+  );
+  if (!hasPermission) {
+    return {
+      success: false,
+      created: 0,
+      failed: 0,
+      duplicateCodes: [],
+      error: 'Insufficient permissions'
+    };
+  }
+
+  const codes = normalizeBatchCodes(data.codes);
+  if (codes.length === 0) {
+    return {
+      success: false,
+      created: 0,
+      failed: 0,
+      duplicateCodes: [],
+      error: 'CODES_REQUIRED'
+    };
+  }
+
+  if (codes.length > BATCH_MAX_CODES) {
+    return {
+      success: false,
+      created: 0,
+      failed: 0,
+      duplicateCodes: [],
+      error: 'BATCH_TOO_LARGE'
+    };
+  }
+
+  let created = 0;
+  let failed = 0;
+  const duplicateCodes: string[] = [];
+
+  const shared = {
+    tokenAmount: data.tokenAmount,
+    maxUses: data.maxUses,
+    expiresAt: data.expiresAt ?? null,
+    tokenExpiresAt: data.tokenExpiresAt ?? null,
+    coinPoolId: data.coinPoolId ?? null,
+    createdById: user.id
+  };
+
+  for (const code of codes) {
+    try {
+      await prisma.invitationCode.create({
+        data: { ...shared, code }
+      });
+      created++;
+    } catch (error) {
+      if (
+        error instanceof Prisma.PrismaClientKnownRequestError &&
+        error.code === 'P2002'
+      ) {
+        duplicateCodes.push(code);
+      } else {
+        failed++;
+      }
+    }
+  }
+
+  if (created > 0) {
+    revalidatePath('/admin/invitation-codes');
+  }
+
+  return {
+    success: created > 0,
+    created,
+    failed,
+    duplicateCodes
+  };
+}
