+  const router = useRouter();
+  const [open, setOpen] = useState(false);
+  const [mode, setMode] = useState<Mode>('new');
+  const [coinPoolAdminRoleId, setCoinPoolAdminRoleId] = useState<string>('');
+  const [isLoadingRoles, setIsLoadingRoles] = useState(false);
+  const [isSubmittingNew, setIsSubmittingNew] = useState(false);
+  const [isSubmittingExisting, setIsSubmittingExisting] = useState(false);
+
+  const form = useForm<CreateUserFormValues>({
+    resolver: zodResolver(CreateUserSchema),
+    defaultValues: {
+      name: '',
+      email: '',
+      password: '',
+      confirmPassword: '',
+      adminRoleId: '',
+      initialTokenAmount: undefined,
+      assignedBusinessAdmin: '',
+      coinPoolPermission: '',
+      organizationName: ''
+    }
+  });
+
+  const [existingUserId, setExistingUserId] = useState<string>('');
+  const [existingBusinessAdminId, setExistingBusinessAdminId] =
+    useState<string>('');
+
+  useEffect(() => {
+    if (open) {
+      setIsLoadingRoles(true);
+      fetch('/api/admin/roles/assignable')
+        .then((res) => res.json())
+        .then(
+          (data: {
+            success?: boolean;
+            roles?: Array<{ id: string; name: string }>;
+          }) => {
+            if (data.success && data.roles) {
+              const role = data.roles.find((r) => r.name === 'coin-pool-admin');
+              if (role) setCoinPoolAdminRoleId(role.id);
+            }
+          }
+        )
+        .finally(() => setIsLoadingRoles(false));
+    }
+  }, [open]);
+
+  const handleSubmitNew = async (values: CreateUserFormValues) => {
+    if (!coinPoolAdminRoleId) {
+      toast.error(tCreateUser('error.insufficientPermissions'));
+      return;
+    }
+    setIsSubmittingNew(true);
+    try {
+      const result = await createUser({
+        ...values,
+        adminRoleId: coinPoolAdminRoleId,
+        assignedBusinessAdmin: values.assignedBusinessAdmin || undefined,
+        initialTokenAmount: values.initialTokenAmount
+      });
+      if (result.error) {
+        toast.error(result.error);
+        return;
+      }
+      toast.success(tCreateUser('success.userCreated'));
+      setOpen(false);
+      form.reset();
+      router.refresh();
+    } finally {
+      setIsSubmittingNew(false);
+    }
+  };
