+'use client';
+
+import { Pencil } from 'lucide-react';
+import Link from 'next/link';
+import { useTranslations } from 'next-intl';
+
+import { Button } from '@/components/ui/button';
+import {
+  Table,
+  TableBody,
+  TableCell,
+  TableHead,
+  TableHeader,
+  TableRow
+} from '@/components/ui/table';
+import { Badge } from '@/components/ui/badge';
+import { updateBaseModelTokenCost } from '@/actions/base-model';
+import type { BaseModelWithRecommendedParameters } from '@/data/base-model';
+
+import { InlineTokenCostCell } from './inline-token-cost-cell';
+
+interface CheckpointsTableProps {
+  baseModels: BaseModelWithRecommendedParameters[];
+}
+
+export function CheckpointsTable({ baseModels }: CheckpointsTableProps) {
+  const t = useTranslations('admin.checkpoints');
+
+  const handleTokenCostSave = async (id: string, tokenCost: number | null) => {
+    const result = await updateBaseModelTokenCost(id, tokenCost);
+    return { tokenCost: result.tokenCost };
+  };
+
+  return (
+    <Table>
+      <TableHeader>
+        <TableRow>
+          <TableHead>{t('name')}</TableHead>
+          <TableHead>{t('fileName')}</TableHead>
+          <TableHead>{t('version')}</TableHead>
+          <TableHead>{t('baseModel')}</TableHead>
+          <TableHead>{t('license')}</TableHead>
+          <TableHead>{t('status')}</TableHead>
+          <TableHead>{t('tokenCost')}</TableHead>
+          <TableHead>{t('hasRecommendedParams')}</TableHead>
+          <TableHead>{t('actions')}</TableHead>
+        </TableRow>
+      </TableHeader>
+      <TableBody>
+        {baseModels.length === 0 ? (
+          <TableRow>
+            <TableCell colSpan={9} className="text-center">
+              {t('noBaseModels')}
+            </TableCell>
+          </TableRow>
+        ) : (
+          baseModels.map((model) => (
+            <TableRow key={model.id}>
+              <TableCell className="font-medium">{model.name}</TableCell>
+              <TableCell>{model.fileName}</TableCell>
+              <TableCell>{model.version}</TableCell>
+              <TableCell>{model.baseModel || '-'}</TableCell>
+              <TableCell>
+                {model.license ? (
+                  <Link
+                    href={model.licenseUrl || '#'}
+                    target={model.licenseUrl ? '_blank' : '_self'}
+                    className="hover:underline text-blue-600"
+                  >
+                    {model.license}
+                  </Link>
+                ) : (
+                  '-'
+                )}
+              </TableCell>
+              <TableCell>
+                {model.isActive ? (
+                  <Badge
+                    variant="outline"
+                    className="bg-green-50 text-green-700 border-green-200"
+                  >
+                    {t('active')}
+                  </Badge>
+                ) : (
+                  <Badge
+                    variant="outline"
+                    className="bg-gray-50 text-gray-500 border-gray-200"
+                  >
+                    {t('inactive')}
+                  </Badge>
+                )}
+              </TableCell>
+              <TableCell>
+                <InlineTokenCostCell
+                  baseModelId={model.id}
+                  initialValue={model.tokenCost}
+                  onSave={handleTokenCostSave}
+                />
+              </TableCell>
+              <TableCell>
+                {model.recommendedParameters ? (
+                  <Badge
+                    variant="outline"
+                    className="bg-green-50 text-green-700 border-green-200"
+                  >
+                    {t('yes')}
+                  </Badge>
+                ) : (
+                  <Badge
+                    variant="outline"
+                    className="bg-gray-50 text-gray-500 border-gray-200"
+                  >
+                    {t('no')}
+                  </Badge>
