+'use client';
+
+import { useRouter, useSearchParams } from 'next/navigation';
+import { useCallback, useState } from 'react';
+import { useTranslations } from 'next-intl';
+
+import { FilterAndSearch } from '@/components/admin/filter-and-search';
+import { SearchInput } from '@/components/ui/search-input';
+import BusinessAdminSelector from '@/components/admin/business-admin-selector';
+
+interface CoinPoolSearchFormProps {
+  initialNameSearch?: string;
+  initialBusinessAdminUserId?: string;
+}
+
+export default function CoinPoolSearchForm({
+  initialNameSearch = '',
+  initialBusinessAdminUserId = ''
+}: CoinPoolSearchFormProps) {
+  const t = useTranslations('admin.coinPoolManagement');
+  const router = useRouter();
+  const searchParams = useSearchParams();
+
+  const [nameSearch, setNameSearch] = useState(initialNameSearch);
+  const [businessAdminUserId, setBusinessAdminUserId] = useState(
+    initialBusinessAdminUserId
+  );
+
+  const applyFilters = useCallback(
+    (name: string, businessAdmin: string) => {
+      const params = new URLSearchParams(searchParams.toString());
+      params.set('page', '1');
+      if (name.trim()) {
+        params.set('nameSearch', name.trim());
+      } else {
+        params.delete('nameSearch');
+      }
+      if (businessAdmin.trim()) {
+        params.set('businessAdminUserId', businessAdmin.trim());
+      } else {
+        params.delete('businessAdminUserId');
+      }
+      router.push(`?${params.toString()}`);
+    },
+    [router, searchParams]
+  );
+
+  const handleSearch = (value: string) => {
+    setNameSearch(value);
+    applyFilters(value, businessAdminUserId);
+  };
+
+  const handleBusinessAdminChange = (value: string) => {
+    setBusinessAdminUserId(value);
+    applyFilters(nameSearch, value);
+  };
+
+  return (
+    <FilterAndSearch>
+      <SearchInput
+        placeholder={t('search.namePlaceholder')}
+        value={nameSearch}
+        onSearch={handleSearch}
+      />
+      <div className="w-[240px]">
+        <BusinessAdminSelector
+          value={businessAdminUserId}
+          onValueChange={handleBusinessAdminChange}
+          placeholder={t('search.businessAdminPlaceholder')}
+        />
+      </div>
+    </FilterAndSearch>
+  );
+}
