+'use client';
+
+import { useState, useEffect } from 'react';
+import { useTranslations } from 'next-intl';
+import { useRouter } from 'next/navigation';
+import { toast } from 'sonner';
+
+import {
+  Dialog,
+  DialogContent,
+  DialogDescription,
+  DialogHeader,
+  DialogTitle
+} from '@/components/ui/dialog';
+import { Button } from '@/components/ui/button';
+import BusinessAdminMultiSelector from '@/components/admin/business-admin-multi-selector';
+import LoadingButton from '@/components/button/loading-button';
+import { ERROR_IDS } from '@/constants/errorIds';
+import { CoinPoolWithAccess } from '@/data/admin/coin-pools';
+
+interface EditCoinPoolAccessDialogProps {
+  pool: CoinPoolWithAccess;
+  open: boolean;
+  onOpenChange: (open: boolean) => void;
+}
+
+export default function EditCoinPoolAccessDialog({
+  pool,
+  open,
+  onOpenChange
+}: EditCoinPoolAccessDialogProps) {
+  const t = useTranslations('admin.coinPoolManagement.editAccess');
+  const tError = useTranslations('errors');
+  const tCommon = useTranslations('common');
+  const router = useRouter();
+
+  const getErrorMessage = (errorId: string | undefined): string => {
+    if (!errorId) return t('error');
+    if (errorId === ERROR_IDS.COIN_POOL_ACCESS_NO_PERMISSION)
+      return tError('NO_PERMISSION');
+    if (errorId === ERROR_IDS.COIN_POOL_ACCESS_UNAUTHORIZED)
+      return tError('LOGIN_REQUIRED');
+    return tError(errorId as Parameters<typeof tError>[0]);
+  };
+  const [userIds, setUserIds] = useState<string[]>(() =>
+    pool.coinPoolAccess.map((a) => a.user.id)
+  );
+  const [isLoading, setIsLoading] = useState(false);
+
+  useEffect(() => {
+    if (open) {
+      setUserIds(pool.coinPoolAccess.map((a) => a.user.id));
+    }
+  }, [open, pool.coinPoolAccess]);
+
+  const handleSubmit = async (e: React.FormEvent) => {
+    e.preventDefault();
+    setIsLoading(true);
+    try {
+      const res = await fetch(`/api/admin/coin-pools/${pool.id}/access`, {
+        method: 'PATCH',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify({ userIds: userIds.filter(Boolean) })
+      });
+      const data = await res.json();
+      if (!res.ok || !data.success) {
+        toast.error(getErrorMessage(data.error));
+        return;
+      }
+      toast.success(t('success'));
+      onOpenChange(false);
+      router.refresh();
+    } catch {
+      toast.error(t('error'));
+    } finally {
+      setIsLoading(false);
+    }
+  };
+
+  return (
+    <Dialog open={open} onOpenChange={onOpenChange}>
+      <DialogContent className="sm:max-w-[480px]">
+        <DialogHeader>
+          <DialogTitle>{t('title')}</DialogTitle>
+          <DialogDescription>
+            {pool.name || pool.email || pool.id}
+          </DialogDescription>
+        </DialogHeader>
+        <form onSubmit={handleSubmit} className="space-y-4">
+          <BusinessAdminMultiSelector
+            label={t('businessAdminLabel')}
+            value={userIds}
+            onValueChange={setUserIds}
+            placeholder={t('businessAdminLabel')}
+          />
+          <div className="flex justify-end gap-2">
+            <Button
+              type="button"
+              variant="outline"
+              onClick={() => onOpenChange(false)}
+              disabled={isLoading}
+            >
+              {tCommon('button.cancel')}
+            </Button>
+            <LoadingButton
+              type="submit"
+              loading={isLoading}
+              disabled={isLoading}
+            >
+              {tCommon('button.confirm')}
+            </LoadingButton>
+          </div>
+        </form>
+      </DialogContent>
+    </Dialog>
+  );
+}
